queries:
SELECT AVG(wins) FROM driverStandings WHERE points >= 1 AND wins IS NOT NULL;
SELECT AVG(wins) FROM driverStandings WHERE points > 0
SELECT AVG(wins)
FROM (
  SELECT ds.wins, ds.points,
         ROW_NUMBER() OVER (PARTITION BY ds.driverId, r.year ORDER BY r.round DESC) AS rn
  FROM driverStandings ds
  JOIN races r ON ds.raceId = r.raceId
)
WHERE rn = 1 AND points >= 1;
SELECT AVG(w) FROM (SELECT MAX(ds.wins) AS w FROM driverStandings ds JOIN races r ON ds.raceId = r.raceId GROUP BY r.year, ds.driverId HAVING MAX(ds.points) >= 1);
SELECT AVG(avg_wins) FROM (SELECT AVG(wins) AS avg_wins FROM driverStandings WHERE points >= 1 GROUP BY driverId)
SELECT AVG(season_avg) FROM (
  SELECT AVG(ds.wins) AS season_avg
  FROM driverStandings ds
  JOIN races r ON ds.raceId = r.raceId
  WHERE ds.points >= 1
  GROUP BY r.year
);
